create extension if not exists pgcrypto;
create table public.item_categories(slug text primary key,name text not null,sort_order int unique not null);
insert into public.item_categories values('clothes','Одежда и обувь',1),('home','Дом и мебель',2),('media','Книги, винил и ретро-техника',3),('antiques','Антиквариат и украшения',4),('flea','Барахолка / Всё подряд',5) on conflict do nothing;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique,role text not null default 'contributor' check(role in('curator','contributor','owner')),is_verified boolean not null default false,created_at timestamptz default now());
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,username,role) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'username',''),nullif(split_part(coalesce(new.email,''),'@',1),''),'member'),'contributor') on conflict(id) do nothing;return new;end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create table public.cities(id uuid primary key default gen_random_uuid(),name text not null,country text not null,currency text not null,slug text unique not null,lat float8,lng float8,is_featured boolean default false,created_at timestamptz default now());
create table public.places(id uuid primary key default gen_random_uuid(),city_id uuid references public.cities(id) on delete cascade not null,owner_id uuid references public.profiles(id) on delete set null,name text not null,place_type text check(place_type in('shop','cluster_street','flea_zone')) not null,categories text[] default '{}',price_min int,price_max int,price_note text,address text,lat float8,lng float8,route_coords jsonb,schedule text,socials jsonb default '{}',description text,style_tags text[] default '{}',status text default 'pending' check(status in('approved','pending','questionable','closed')),is_point_verified boolean default false,is_assortment_verified boolean default false,last_confirmed_at timestamptz,closed_reports_count int default 0,live_signal_text text,live_signal_expires_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now(),check(categories <@ array['clothes','home','media','antiques','flea']::text[]),check(price_min is null or price_min>=0),check(price_max is null or price_max>=0));
create table public.events(id uuid primary key default gen_random_uuid(),city_id uuid references public.cities(id) on delete cascade not null,created_by uuid references public.profiles(id) on delete set null,title text not null,categories text[] default '{}',description text,address text,lat float8,lng float8,start_date timestamptz not null,end_date timestamptz not null,social_link text,status text default 'pending' check(status in('approved','pending')),created_at timestamptz default now());
create table public.online_markets(id uuid primary key default gen_random_uuid(),country text not null,city_id uuid references public.cities(id) on delete set null,name text not null,url text not null,categories text[] default '{}',guide_text text,requires_local_phone boolean default false,has_delivery boolean default false,created_at timestamptz default now());
create table public.reviews(id uuid primary key default gen_random_uuid(),place_id uuid references public.places(id) on delete cascade not null,author_id uuid references public.profiles(id) on delete set null,curation_score int2 check(curation_score between 1 and 5),price_score int2 check(price_score between 1 and 5),loot_score int2 check(loot_score between 1 and 5),confirmed_categories text[] default '{}',comment text,created_at timestamptz default now());
create table public.finds(id uuid primary key default gen_random_uuid(),place_id uuid references public.places(id) on delete set null,author_id uuid references public.profiles(id) on delete set null,item_name text not null,price_paid int,currency text not null,category text not null,photo_url text,created_at timestamptz default now());
alter table public.item_categories enable row level security;alter table public.profiles enable row level security;alter table public.cities enable row level security;alter table public.places enable row level security;alter table public.events enable row level security;alter table public.online_markets enable row level security;alter table public.reviews enable row level security;alter table public.finds enable row level security;
create policy "Public read categories" on public.item_categories for select to anon,authenticated using(true);create policy "Public read profiles" on public.profiles for select to anon,authenticated using(true);create policy "Public read cities" on public.cities for select to anon,authenticated using(true);create policy "Public read places" on public.places for select to anon,authenticated using(true);create policy "Public read events" on public.events for select to anon,authenticated using(true);create policy "Public read markets" on public.online_markets for select to anon,authenticated using(true);create policy "Public read reviews" on public.reviews for select to anon,authenticated using(true);create policy "Public read finds" on public.finds for select to anon,authenticated using(true);
create policy "Authenticated create places" on public.places for insert to authenticated with check(owner_id=auth.uid());create policy "Place owner updates" on public.places for update to authenticated using(owner_id=auth.uid());create policy "Event creator insert" on public.events for insert to authenticated with check(created_by=auth.uid());create policy "Review author insert" on public.reviews for insert to authenticated with check(author_id=auth.uid());create policy "Find author insert" on public.finds for insert to authenticated with check(author_id=auth.uid());
insert into public.cities(name,country,currency,slug,lat,lng,is_featured) values('Казань','Россия','₽','kazan',55.7961,49.1064,true),('Нови-Сад','Сербия','RSD','novi-sad',45.2671,19.8335,true) on conflict(slug) do nothing;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('finds-photos','finds-photos',true,5242880,array['image/jpeg','image/png','image/webp','image/gif']) on conflict(id) do update set public=true,file_size_limit=5242880,allowed_mime_types=excluded.allowed_mime_types;
create policy "Public photo read" on storage.objects for select to anon,authenticated using(bucket_id='finds-photos');create policy "Auth photo upload" on storage.objects for insert to authenticated with check(bucket_id='finds-photos' and (storage.foldername(name))[1]=auth.uid()::text);
